<script setup lang="ts">
import {ref,watch} from 'vue'
import {api} from '../api'
import {useRequestScope} from '../platform/request-scope'
const props=defineProps<{refresh?:number;storyId?:string;profileId?:string}>(),capture=useRequestScope(),rows=ref<any[]>([]),offset=ref(0),busy=ref(false),error=ref('')
const kinds:Record<string,string>={world_turn:'一次世界行动',world_character_chat:'一条独立聊天回复',world_write:'连续写作',world_rewrite:'正文改写',world_prepare:'世界准备',world_script_breakdown:'故事拆解',role_chat:'一条人物回复',connection_test:'模型连接测试'}
const phases:Record<string,string>={analysis:'分析与规划',generation:'生成正文',validation:'核验结果',review:'核验结果',breakdown:'拆解故事'}
function duration(v:number|null){return v==null?'尚无记录':(v/1000).toFixed(1)+' 秒'}
async function load(){const scope=capture();busy.value=true;error.value='';try{const params=new URLSearchParams({offset:String(offset.value),...(props.storyId?{storyId:props.storyId}:{}),...(props.profileId?{profileId:props.profileId}:{})});const data=await api<any>('/experience/usage-actions?'+params);if(scope.valid())rows.value=data.items}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
watch(()=>[props.refresh,props.storyId,props.profileId],()=>{offset.value=0;void load()},{immediate:true})
</script>
<template><section aria-label="按行动整理的用量"><h2>每次行动的模型使用</h2><p>一次行动可能包含分析、正文和核验，多次调用会合并显示。平台积分、模型调用预算和供应商费用分别计算。</p><p v-if="error" role="alert">{{error}} <button @click="load">重试</button></p><p v-if="busy" role="status">正在整理使用记录…</p><p v-if="!busy&&!rows.length">尚无模型使用记录。</p><article v-for="row in rows" :key="row.id" class="workspace-card"><h3>{{kinds[row.kind]||'阅读与创作任务'}} · {{row.story?.title||'未关联作品'}}</h3><p>{{new Date(row.createdAt).toLocaleString()}} · {{row.summary.calls}} 次调用<span v-if="row.summary.notSentCalls">，另有 {{row.summary.notSentCalls}} 次确认未发送</span></p><p>输入 {{row.summary.inputTokens??'未知'}} / 输出 {{row.summary.outputTokens??'未知'}} token</p><p v-for="(amount,currency) in row.summary.knownCostByCurrency" :key="currency">已知供应商费用：{{currency}} {{amount}}</p><p v-if="row.summary.unknownCostCalls">{{row.summary.unknownCostCalls}} 条费用未知或使用供应商套餐，不能当作免费。</p><p>首次调用前等待 {{duration(row.timings.beforeFirstCallMs)}} · 首次正文 {{duration(row.timings.firstTextMs)}} · 完整任务 {{duration(row.timings.totalMs)}}</p><details><summary>查看各阶段和核查编号</summary><p>任务 {{row.id}}。首次正文以服务端首次持久接收的公开片段计时；没有事件时显示无记录。</p><p v-for="call in row.calls" :key="call.id">{{phases[call.phase.split(':')[0]]||'辅助处理'}} · {{call.profile.name}} · {{call.status==='not_sent'?'确认未发送':call.status==='completed'?'已收到回执':'发送状态待核查'}} · 输入 {{call.inputTokens??'未知'}} / 输出 {{call.outputTokens??'未知'}} token</p><RouterLink :to="{path:'/help/feedback',query:{task:row.id,from:'/settings/models'}}">反馈此任务</RouterLink></details></article><div class="actions"><button :disabled="busy||offset===0" @click="offset=Math.max(0,offset-20);load()">上一页行动</button><button :disabled="busy||rows.length<20" @click="offset+=20;load()">下一页行动</button></div></section></template>
<style scoped>article{margin:20px 0}p{overflow-wrap:anywhere;line-height:1.8}button,summary{min-height:44px}summary{cursor:pointer}</style>
